mapper.select:
SELECT SEARCH_SEQ AS searchSeq , DATE_FORMAT(SEARCH_DT, '%Y-%m-%d %T' ) AS searchDt , SEARCH_TYPE AS searchType , SEARCH_ID AS searchId , SEARCH_NAME AS searchName , P_FILTER_SEQ AS pFilterSeq , FILTER_SEQ AS filterSeq , FILTER_NM AS filterNm , CONSENT_NO AS consentNo , CONSENT_USER_ID AS consentUserId , CONSENT_NAME AS consentName , CONDITIONS AS conditions FROM UI_MSG_SEARCH_LOG WHERE 1 = 1
AND SEARCH_DT BETWEEN STR_TO_DATE( CONCAT(#{startDt}, '000000'), '%Y%m%d%H%i%s') AND STR_TO_DATE( CONCAT(#{endDt}, '235959'), '%Y%m%d%H%i%s')
AND SEARCH_ID = #{adminId}
AND SEARCH_TYPE = #{searchType}
ORDER BY SEARCH_DT DESC
